import {
  applyParamsToScript,
  applyDoubleCborEncoding,
  validatorToScriptHash,
  type MintingPolicy,
} from "@lucid-evolution/lucid";
import { fromHex } from "@lucid-evolution/lucid";

export function getCertificatePolicy(): MintingPolicy {
  const registryScriptHash = "5ae39bf8f081a3a4bbd823c1beb0ce09e3d47f4b56e959aa582de7cb";
    const compiledCode = "";

  // Apply registry_script_hash as a ByteArray parameter
  const applied = applyParamsToScript(
    applyDoubleCborEncoding(compiledCode),
    [registryScriptHash]   // ByteArray → pass as hex string
  );

  return { type: "PlutusV3", script: applied };
}

export function getCertificatePolicyId(): string {
  return validatorToScriptHash(getCertificatePolicy());
}
console.log("Certificate Policy ID:", getCertificatePolicyId());